{
"company": "Dayjoy",
"source_file": "Dayjoy Product Brochure, FSSAI License, Policies, Income Disclaimer",
"fields": {
"about_dayjoy": "Dayjoy Marketing Pvt. Ltd. is a wellness brand and direct selling company offering high-quality lifestyle products across Wellness, Beauty, Agriculture, Clothing, Spices, and Home Care. Operating under the Adila Group, it empowers individuals through a smart direct selling business model.",
"mission": "To create values for our customers through products of the highest quality backed by the guarantee of satisfaction while maintaining our uncompromising values & principles as we grow.",
"vision": "We aim to set a new benchmark in direct selling segment along with creating a world of opportunities so that people do not have to compromise with their living standards, and they can live a life of economic independence.",
"leadership": [
{
"name": "Anmol Agarwal",
"role": "Founder & Managing Director",
"evidence": "Brochure Page 3"
},
{
"name": "Divyansh Agarwal",
"role": "Founder & Managing Director",
